{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "Stat",
    "displayName": "Stat",
    "category": "Content",
    "keywords": [
      "stat",
      "kpi",
      "metric",
      "number",
      "value",
      "delta",
      "trend",
      "dashboard",
      "statistic",
      "measure"
    ],
    "props": [
      {
        "name": "label",
        "type": "string",
        "description": "Metric name shown above the value, e.g. \"Total requests\".",
        "required": true
      },
      {
        "name": "value",
        "type": "ReactNode",
        "description": "Headline metric rendered large with tabular numerals. Pass a pre-formatted string like \"1.2M\".",
        "required": true
      },
      {
        "name": "delta",
        "type": "{value: string, direction: 'up' | 'down' | 'flat', sentiment?: 'positive' | 'negative' | 'neutral'}",
        "description": "Change indicator next to the value: an up/down/flat glyph plus colored text. sentiment overrides the direction color mapping (up=positive, down=negative, flat=neutral) for inverted metrics like error rate."
      },
      {
        "name": "description",
        "type": "string",
        "description": "Muted supporting line under the value, e.g. \"vs. previous 30 days\"."
      },
      {
        "name": "media",
        "type": "ReactNode",
        "description": "Trend slot rendered below the text content, e.g. a sparkline or mini chart. Stat does not render a chart itself."
      },
      {
        "name": "size",
        "type": "'sm' | 'md' | 'lg'",
        "description": "Size variant controlling the value's font size.",
        "default": "'md'"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-stat",
          "visualProps": [
            "size"
          ]
        }
      ]
    },
    "usage": {
      "description": "A KPI/metric display for dashboards and summary rows: metric name, large tabular-nums value, an optional sentiment-aware delta, a supporting description, and a media slot for a sparkline or mini chart. Compose several in a Grid for a KPI row.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Pass pre-formatted strings for value and delta (\"1.2M\", \"+12.4%\"); Stat does not format numbers."
        },
        {
          "guidance": true,
          "description": "Set `sentiment` explicitly for inverted metrics where down is good, like error rate or latency."
        },
        {
          "guidance": true,
          "description": "Wrap Stat in a Card and lay out KPI rows with Grid columns={{minWidth: 240, max: 4}}."
        },
        {
          "guidance": false,
          "description": "Put a full-size chart in the media slot; it is meant for compact sparklines or trend glyphs."
        },
        {
          "guidance": false,
          "description": "Rely on delta color alone to convey meaning; the direction glyph and screen-reader text carry it too."
        }
      ]
    },
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
